// What the traveller needs to know about a generated plan, taken from the
// trip's `note` (chatbot-service routes_tripplanner.py, also stored with a
// saved trip): a must-go place that was not found or could not be fitted in,
// and public holidays inside the trip dates. The note is one string of
// " | "-separated parts whose first part is an internal "Generated by AI
// (model)" marker -- that one, and the "Not found" placeholder of an empty
// plan, are not for display.
const INTERNAL_PART = /^(Generated by AI\b|Not found$)/

export function tripNotices(note) {
  if (typeof note !== 'string') return []
  return note.split(' | ').map((part) => part.trim()).filter((part) => part && !INTERNAL_PART.test(part))
}
